#include <cstdio>
#include <algorithm>
using namespace std;

const int MAXN = 200005;
int N, M;
long long bitB[MAXN], bitA[MAXN];

// BIT de diferenças: range add, point query via prefixo
void upd(long long *bit, int idx, long long val) {
    for (; idx <= N; idx += idx & (-idx)) bit[idx] += val;
}

long long qry(long long *bit, int idx) {
    long long s = 0;
    for (; idx > 0; idx -= idx & (-idx)) s += bit[idx];
    return s;
}

// Adiciona (alpha * p + beta) a cada posicao p no intervalo [l, r]
void rangeAdd(int l, int r, long long alpha, long long beta) {
    upd(bitB, l, beta);
    if (r + 1 <= N) upd(bitB, r + 1, -beta);
    upd(bitA, l, alpha);
    if (r + 1 <= N) upd(bitA, r + 1, -alpha);
}

int main() {
    scanf("%d %d", &N, &M);
    while (M--) {
        int type;
        scanf("%d", &type);
        if (type == 3) {
            int i;
            scanf("%d", &i);
            long long ans = qry(bitB, i) + qry(bitA, i) * (long long)i;
            printf("%lld\n", ans);
        } else {
            int i, v;
            scanf("%d %d", &i, &v);
            if (type == 1) {
                // FRENTE i V: posicao p (i..min(N, i+V-1)) recebe V + i - p
                int r = (int)min((long long)N, (long long)i + v - 1);
                rangeAdd(i, r, -1, (long long)v + i);
            } else {
                // TRAS i V: posicao p (max(1, i-V+1)..i) recebe p + V - i
                int l = max(1, i - v + 1);
                rangeAdd(l, i, 1, (long long)v - i);
            }
        }
    }
    return 0;
}
